<script lang="ts">
  import { t } from "$lib/i18n/typedI18n";
  import type { TranslationKey } from "$lib/types/i18n";
  import { gameSettingsState } from "$lib/stores/gameSettingsState.svelte";
  import type { KeybindingAction } from "$lib/stores/gameSettingsTypes";
  import { onMount } from "svelte";
  import { userActionService } from "$lib/services/userActionService";
  import { modalStateRune } from "$lib/stores/modalState.svelte";
  import KeybindingButton from "./KeybindingButton.svelte";
  import StyledButton from "$lib/components/ui/StyledButton.svelte";
  import { actionGroups } from "$lib/config/hotkeyConfig";

  let listeningFor = $state<{ action: KeybindingAction; index: number } | null>(null);

  const settings = $derived(gameSettingsState.state);
  let keybindings = $derived(settings.keybindings);

  let conflicts = $derived((() => {
    const counts: Record<string, number> = {};
    const conflictKeys = new Set<string>();
    // Явне приведення типів для Object.values
    const allKeys = Object.values(keybindings) as string[][];
    for (const keys of allKeys) {
      for (const key of keys) {
        counts[key] = (counts[key] || 0) + 1;
        if (counts[key] > 1) {
          conflictKeys.add(key);
        }
      }
    }
    return conflictKeys;
  })());

  function listenForKey(action: KeybindingAction, index: number = -1) {
    listeningFor = { action, index };
  }

  function removeKey(action: KeybindingAction, index: number) {
    const newKeybindings = { ...settings.keybindings };
    const updatedKeys = [...(newKeybindings[action] || [])];
    updatedKeys.splice(index, 1);
    newKeybindings[action] = updatedKeys;
    gameSettingsState.update((s) => ({ ...s, keybindings: newKeybindings }));
  }

  function handleKeydown(event: KeyboardEvent) {
    if (modalStateRune.state.isOpen) return;
    if (listeningFor) {
      event.preventDefault();
      if (event.code === "Escape") {
        listeningFor = null;
        return;
      }
      const { action, index } = listeningFor;
      const newKeybindings = { ...settings.keybindings };
      const keysForAction = [...(newKeybindings[action] || [])];
      if (index !== -1) {
        keysForAction[index] = event.code;
      } else {
        keysForAction.push(event.code);
      }
      newKeybindings[action] = keysForAction;
      gameSettingsState.update((s) => ({ ...s, keybindings: newKeybindings }));
      listeningFor = null;
    }
  }

  onMount(() => {
    window.addEventListener("keydown", handleKeydown);
    return () => {
      window.removeEventListener("keydown", handleKeydown);
    };
  });
</script>

<div class="hotkeys-tab">
  {#each actionGroups as group (group.title)}
    <h3 class="group-title">{$t(group.title as TranslationKey)}</h3>
    <div class="key-grid">
      {#each group.actions as action (action)}
        <div class="key-item">
          <span class="action-name"
            >{$t(`controlsPage.actions.${action}` as TranslationKey)}</span
          >
          <div class="key-buttons-container">
            {#each keybindings[action] || [] as key, i}
              <KeybindingButton
                keyName={key}
                isListening={listeningFor?.action === action &&
                  listeningFor?.index === i}
                hasConflict={conflicts.has(key)}
                onclick={() => listenForKey(action, i)}
                onremove={() => removeKey(action, i)}
              />
            {/each}
            {#if (keybindings[action]?.length || 0) < 8}
              {#if listeningFor?.action === action && listeningFor?.index === -1}
                <span class="press-key-hint"
                  >{$t("controlsPage.pressKey") || "Натисніть клавішу"}</span
                >
              {:else}
                <button
                  class="add-key-btn"
                  aria-label={$t("controlsPage.addKey")}
                  onclick={() => listenForKey(action, -1)}>+</button
                >
              {/if}
            {/if}
          </div>
        </div>
      {/each}
    </div>
  {/each}

  <div class="controls-footer">
    {#if conflicts.size > 0}
      <p class="conflict-warning">{$t("controlsPage.keyConflict")}</p>
    {/if}
    <!--
      `StyledButton`, а не власна кнопка — і це не косметика.

      Доти тут стояв `<button class="reset-button">`, у якого в стилях були лише
      `padding`, `background` і `cursor: pointer`. Ні `:hover`, ні `:active`, ні
      `:focus-visible` — тобто натискання не давало ЖОДНОГО відгуку: людина не
      бачила, що кнопка спрацювала, а той, хто ходить Tab-ом, не бачив навіть,
      де він стоїть.

      Усі три стани вже описані один раз у `styled-button.css`
      (`:active` — `translateY(1px)`, `:hover` — підйом і `brightness(1.1)`,
      `:focus-visible` — рамка 3px). Дописувати їх тут четвертим місцем означало
      б четвертий набір, який розійдеться з рештою; варіант `warning` дає ще й
      ті самі кольори, які ця кнопка й так вживала (`--warning-action-bg/-text`).

      Обгортка потрібна, бо `.styled-button` — `width: 100%`: `inline-block`
      стискає її до вмісту, і кнопка лишається такою ж, як була. Клас на
      обгортці, а не переданий у компонент: scoped-стиль Svelte не доїжджає до
      елемента, який малює інший компонент.
    -->
    <div class="reset-button-wrapper">
      <StyledButton
        variant="warning"
        onclick={userActionService.resetKeybindings}
        dataTestId="hotkeys-reset-btn"
      >
        {$t("controlsPage.resetToDefaults")}
      </StyledButton>
    </div>
  </div>
</div>

